import logging
import time

from .tcp import TcpPdu
from .base import PduIdentificationType
from ..exceptions import PduConnectionError, BadResponse
from ..device_status import DeviceStatus


class Keysight(TcpPdu):
    """The Keysight N8757A is a 60 V, 85 A, 5100 W, single-output power supply
    The Keysight N5767A is a 60 V, 25 A, 1500 W, single-output power supply
    It does not support port numbers, so all commands are sent to the single output."""

    SUPPORTED_MODELS = ["N5767A", "N8757A", "N8738A"]
    MIN_VOLTAGE = 6

    def __init__(
        self, host: str, port: int = 5025, timeout: float = 10, retry_timeout: float = 2
    ) -> None:
        super().__init__(host, port, timeout, retry_timeout)
        _vendor, _model, _serial, _version, _rev = self.get_idn()

        logging.info(
            f"IDN information is vendor: {_vendor}, model:{_model}, "
            f"serial number: {_serial}, version:{_version}, revision: {_rev}"
        )
        self._verify_model(_model)

    def get_idn(self) -> list:
        info = self.get_pdu_info()
        if info.identification_type != PduIdentificationType.SCPI_IDN:
            raise PduConnectionError()
        return [item.strip() for item in info.identifier.split(",")]

    def power_on(self, port=None) -> None:
        self._execute_cmd("OUTPut ON\r\n")
        time.sleep(1)
        self._check_error()

    def power_off(self, port=None) -> None:
        self._execute_cmd("OUTPut OFF\r\n")
        time.sleep(1)
        self._check_error()

    def get_voltage(self, port=None) -> float:
        response = self._execute_cmd_with_retry_on_timeout("MEASure:VOLTage?\r\n")
        return float(response)

    def set_voltage(self, port=None, voltage=None) -> None:
        logging.info(f"power supply target to {voltage:.2f} V")
        current_voltage = self.get_voltage()
        if abs(current_voltage - voltage) > 0.1:
            self._execute_cmd_with_retry_on_timeout(f"SOURce:VOLtage {voltage:.2f}\r\n")
            time.sleep(1)
            self._check_error()

    def get_current(self, port=None) -> float:
        response = self._execute_cmd_with_retry_on_timeout("MEASure:CURRent?\r\n")
        return float(response)

    def reset(self, ports=None, time_interval=10):
        self.power_off()
        time.sleep(time_interval)
        self.power_on()

    def get_port_status(self, port=None):
        v = self.get_voltage()
        return DeviceStatus.OFF if v < self.MIN_VOLTAGE else DeviceStatus.ON

    def _check_error(self) -> None:
        response = self._execute_cmd_with_retry_on_timeout("SYSTem:ERRor?\r\n")
        if '+0,"No error"' not in response:
            raise BadResponse(f"Power supply error: {response}")

    def _verify_model(self, model):
        if model not in self.SUPPORTED_MODELS:
            logging.warning(
                f"Model information from device '{model}' does not match the expected '{self.SUPPORTED_MODELS}'"
            )

    def _parse_response(self, response):
        pass

    @property
    def _port_setting(self) -> dict:
        """Only to satisfy the contract of PDU abstraction"""
        return {
            DeviceStatus.OFF: "OFF",
            DeviceStatus.ON: "ON",
        }

    def _build_command(self, port, status):
        pass
